// === Tab: mySketch ===
let w = 900, h = 900;
let s = 10;
let grid = 3;
let src;
let msk;
let hh = (h - s*8) / grid;
let ww = (w - s*8) / grid;

let p1 = [0, -9];
let p2 = [13, 15];
let p3 = [-13,15];

let p4 = [0, 15];
let p5 = [13, -8];
let p6 = [-13,-8];

let pal = ['#ECAA9C','#B1D1C6', '#2E5B8B', '#F2CA60', '#d4c7a3', '#DE7830', '#513C2C', '#1F3858', '#C9292E', '#bfb8a3'];

function mousePressed() {
  redraw();
}

function setup() {
  createCanvas(w, h);
  pixelDensity(2);
  noLoop();
  smooth();
  colorMode(HSB, 360, 100, 100, 100);
}

function draw() {
  background(220);
  src = createGraphics(w,h); //size of drawing
  src.strokeWeight(2);
  src.pixelDensity(2);
  var cc;
  for(let i = 0; i < 600; i++) {
    cc = color( getColor() );
    if(random() < 0.6) {
      src.noStroke();
      src.fill(cc);    
    } else {
      src.noFill();
      src.stroke(cc);
    }
    src.circle(random(w), random(h), random(60,90));
    src.circle(random(w), random(h), random(10,50));   
  }

  msk = createGraphics(w,h); //size of mask
  msk.rectMode(CENTER);

  for(let i = 0; i < grid; i++) {
    ny = hh * i + s*6 + hh/6;
    for(let j = 0; j < grid; j++) {
      msk.push();

      nx = ww * j + hh/1.75;
      msk.translate(nx + s*2, ny + s*4);

      var pattern = random();
      if(pattern < 0.4) {
        msk.circle(0, s*3, 240);      
      } else if(pattern < 0.6) {
        msk.rect(0, s*3, 200);      
      } else if(pattern < 0.8) {
        msk.triangle(p1[0]*s, p1[1]*s, p2[0]*s, p2[1]*s, p3[0]*s, p3[1]*s);
      } else {
        msk.triangle(p4[0]*s, p4[1]*s, p5[0]*s, p5[1]*s, p6[0]*s, p6[1]*s);
      }
      msk.pop();
    }
  }

  ( masked = src.get()).mask(msk);

  image(masked, 0, 0);

  var step = 0.5;
  var k = random(1, 12);
  var v = random(-0.07, 0.07);
  var pix, n, nx, ny;

  var g = get();
  clear();

  noiseSeed(random(100));
  for (let x = 0; x < w; x += step) {
    pix = g.get(x, 0, 1, h);
    n = noise(x / w * k);
    n = map(n, 0, 1, -1, 1);
    ny = n * h * v;
    image(pix, x, ny);
    image(pix, x, ny - h);
    image(pix, x, ny + h);
  }

  g = get();
  clear();

  noiseSeed(random(100));
  for (let y = 0; y < h; y += step) {
    pix = g.get(0, y, w, 1);
    n = noise(y / h * k);
    n = map(n, 0, 1, -1, 1);
    nx = n * w * v;
    image(pix, nx - w, y);
    image(pix, nx, y);
    image(pix, nx + w, y);
  }

  g = null;

  drawGrids();
  drawFrame();
}


// ------------------------------------- //
// ------------------------------------- //
// ------------------------------------- //

function drawGrids() {
  stroke(0,0,10,100);
  strokeWeight(1.5);
  noFill();
  var tx = int(w / s);
  var ty = int(h / s);
  for(let i = 0; i < ty; i++) {
    cy = i * s;
    for(let j = 0; j < tx; j++) {
      cx = j * s;
      point(cx, cy);
    }
  } 
}

function drawFrame() {
  rectMode(CENTER);
  noStroke();
  fill(220);

  rect(s*2-1, h/2, s*4, h);
  rect(w-s*2+1, h/2, s*4, h);

  rect(w/2, s*2-1, w, s*4);
  rect(w/2, h-s*2+1, w, s*4);
}

function getColor() {
  var l = pal.length;
  var cc = random();
  shuffle(pal, true);

  if(cc < 1/l) {
    return pal[0];
  } else if (cc < 2/l + .05) {
    return pal[1];
  } else if (cc < 3/l - .03) {
    return pal[2];
  } else if (cc < 4/l + .05) {
    return pal[3];
  } else if (cc < 5/l - .02) {
    return pal[4];
  } else if (cc < 6/l + .06) {
    return pal[5];
  } else if (cc < 7/l + .02) {
    return pal[6];
  } else if (cc < 8/l - .01) {
    return pal[7];
  } else if (cc < 9/l + .02) {
    return pal[8];
  } else {
    return pal[9];
  }
}

